const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = ({ title, price, soldOut }) => {
  const cardClass = soldOut ? 'card card--sold' : 'card';

  return (
    <article className={cardClass}>
      <h3 className="card__title">{title}</h3>
      <p className="card__price">{price}</p>
    </article>
  );
};

root.render(
  <>
    <Card title="오버사이즈 셔츠" price="189,000원" soldOut />
    <Card title="니트 베스트" price="245,000원" />
  </>
);

const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = ({ title, price, soldOut, className = '' }) => {
  const cardClass = `card ${soldOut ? 'card--sold' : ''} ${className}`.replace('  ', ' ').trim();

  return (
    <article className={cardClass}>
      <h3 className="card__title">{title}</h3>
      <p className="card__price">{price}</p>
    </article>
  );
};

root.render(
  <>
    <Card title="오버사이즈 셔츠" price="189,000원" soldOut />
    <Card title="니트 베스트" price="245,000원" />
    <Card title="울 코트" price="590,000원" className="card--wide" />
  </>
);
